<script setup>
import { ref } from 'vue';import { useRouter } from 'vue-router';import { Send, ArrowLeft } from '@lucide/vue'
import AppLogo from '../../components/AppLogo.vue';import { api } from '../../services/api';import { uiStore } from '../../stores/ui'
const router=useRouter(),busy=ref(false),done=ref(false),form=ref({code:'',name:'',short_name:'',logo_url:'',username:'',password:''})
async function submit(){busy.value=true;try{await api.post('/auth/register-club',form.value,{auth:false});done.value=true;uiStore.notify('Đã gửi hồ sơ đăng ký CLB.')}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
</script>
<template><div class="register-page"><div class="container"><RouterLink to="/login" class="back"><ArrowLeft :size="17"/>Quay lại đăng nhập</RouterLink><section class="glass form-card"><AppLogo/><div v-if="done" class="success"><div>✅</div><h1>Đã gửi đăng ký</h1><p>Admin FIFA sẽ kiểm tra và kích hoạt tài khoản. Sau khi được duyệt, CLB có thể đăng nhập bằng tài khoản đã tạo.</p><RouterLink to="/login" class="btn btn-primary">Về trang đăng nhập</RouterLink></div><template v-else><div><span class="eyebrow">Club registration</span><h1>Đăng ký câu lạc bộ</h1><p>Mỗi câu lạc bộ sử dụng một tài khoản chung để quản lý đội hình, chuyển nhượng và giải đấu.</p></div><form class="form-grid" @submit.prevent="submit"><label class="form-group"><span class="label">Mã CLB</span><input v-model.trim="form.code" class="input" maxlength="30" required placeholder="DRAGON_FC"/></label><label class="form-group"><span class="label">Tên viết tắt</span><input v-model.trim="form.short_name" class="input" maxlength="50" required placeholder="Dragon"/></label><label class="form-group full"><span class="label">Tên đầy đủ</span><input v-model.trim="form.name" class="input" maxlength="150" required placeholder="Dragon Football Club"/></label><label class="form-group full"><span class="label">URL logo (không bắt buộc)</span><input v-model.trim="form.logo_url" class="input" placeholder="https://..."/></label><label class="form-group"><span class="label">Tên đăng nhập chung</span><input v-model.trim="form.username" class="input" maxlength="80" required/></label><label class="form-group"><span class="label">Mật khẩu</span><input v-model="form.password" class="input" type="password" minlength="8" maxlength="72" required/></label><div class="form-group full actions"><button type="button" class="btn" @click="router.back()">Hủy</button><button class="btn btn-primary" :disabled="busy"><Send :size="17"/>{{ busy?'Đang gửi...':'Gửi đăng ký' }}</button></div></form></template></section></div></div></template>
<style scoped>.register-page{min-height:100vh;padding:34px 0;display:grid;align-items:center}.container{max-width:850px}.back{display:inline-flex;align-items:center;gap:7px;color:var(--muted);font-size:13px;margin-bottom:15px}.form-card{padding:30px;display:grid;gap:30px}.form-card h1{font-size:38px;margin:9px 0}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:10px}.success{text-align:center;padding:34px 12px}.success>div{font-size:64px}.success h1{margin-top:18px}.success p{max-width:560px;margin:0 auto 25px}</style>
